Set-Location "C:\Users\ankou\Desktop\MTL (MonTrajetIntelligent)\montrajet-lyon"
$ErrorActionPreference = 'Stop'
$backup = Join-Path (Get-Location) ('backup-interface-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
New-Item -ItemType Directory -Path $backup -Force | Out-Null
Copy-Item 'src\components\MobilityResults.tsx' (Join-Path $backup 'MobilityResults.tsx')
Copy-Item 'src\App.css' (Join-Path $backup 'App.css')
$component = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
$styles = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[System.IO.File]::WriteAllText((Join-Path (Get-Location) 'src\components\MobilityResults.tsx'), $component, [System.Text.UTF8Encoding]::new($false))
[System.IO.File]::AppendAllText((Join-Path (Get-Location) 'src\App.css'), "`r`n" + $styles, [System.Text.UTF8Encoding]::new($false))
Write-Host "Sauvegarde : $backup" -ForegroundColor Cyan
Write-Host 'Verification TypeScript / build...' -ForegroundColor Cyan
npm run build
if ($LASTEXITCODE -ne 0) { Write-Warning 'Build en erreur. Restaurer les deux fichiers depuis le dossier de sauvegarde indique ci-dessus.'; exit 1 }
Write-Host 'Refonte installee et build reussi.' -ForegroundColor Green
